import { createSlice } from '@reduxjs/toolkit';
import { outfieldType, pitchType, weather } from '../../gameData/matchCondition';
import { battingAction, bowlingAction } from '../../gameData/actionType';
import { matchStatusEnum } from '../../gameData/matchStatusEnum';

const randomKey = (obj) => Object.keys(obj)[Math.floor(Math.random() * Object.keys(obj).length)];

export const buildInitialInnings = () => ({
  score: 0,
  wickets: 0,
  balls: 0,
  wides: 0,
  noBalls: 0,
  commentary: [],
  strikerIndex: null,
  nonStrikerIndex: null,
  nextBatterIndex: 0,
  battingOrderIndices: [],
  needsOpeners: false,
  openerSelections: [],
  outBatterIndices: [],
  waitingForNextBatter: false,
  currentBowlerIndex: null,
  lastOverBowlerIndex: null,
  completedOverBowlerIndices: [],
  waitingForNextBowler: false,
  battingStats: [],
  bowlingStats: [],
  freeHitArmed: false,
  superShotUsedInOver: 0,
  superShotUsedMatch: 0,
  superShotBonus: 0,
  specialBallUsedInOver: 0,
  specialBallUsedMatch: 0,
  specialBallBonus: 0,
  lastEvent: 'Ready for first delivery.',
});

export const buildRandomMatchCondition = () => ({
  weather: randomKey(weather),
  pitch: randomKey(pitchType),
  outfield: randomKey(outfieldType),
});

export const buildEmptyMatchCondition = () => ({
  weather: '',
  pitch: '',
  outfield: '',
});

const initialState = {
  stage: matchStatusEnum.intro,
  gameMode: 'quick',
  seriesLength: 1,
  seriesCurrentMatch: 1,
  seriesResults: [],
  seriesPlayerStats: {},
  tournamentUserTeam: '',
  tournamentOpponentTeams: [],
  tournamentMatches: [],
  tournamentCurrentMatchId: '',
  tournamentChampion: '',
  tournamentPlayerStats: {},
  careerTeam: '',
  careerPlayerProfile: null,
  careerDomesticCountry: '',
  careerDomesticTeams: [],
  careerGlobalPlayerPool: [],
  careerAuctionSummary: null,
  careerOffers: [],
  careerRetired: false,
  careerSeason: 0,
  careerSeasonLength: 'standard',
  careerFormat: 't20',
  careerMatchIndex: 0,
  careerSchedule: [],
  careerStandings: {},
  careerPlayerStats: {},
  careerSeasonHistory: [],
  matchTypeKey: '',
  ownTeam: '',
  opponentTeam: '',
  ownPlayingXI: [],
  opponentPlayingXI: [],
  ownBattingOrderIds: [],
  opponentBattingOrderIds: [],
  ownCustomPlayers: [],
  opponentCustomPlayers: [],
  ownTeamRoles: {
    captainId: null,
    viceCaptainId: null,
    wicketKeeperId: null,
  },
  opponentTeamRoles: {
    captainId: null,
    viceCaptainId: null,
    wicketKeeperId: null,
  },
  locationCountry: '',
  selectedStadium: '',
  commentator: '',
  tossWinner: '',
  tossDecision: '',
  tossCall: '',
  firstBattingSide: '',
  matchCondition: buildEmptyMatchCondition(),
  battingIntent: battingAction.normal,
  bowlingIntent: bowlingAction.normal,
  firstInnings: buildInitialInnings(),
  secondInnings: buildInitialInnings(),
  showScoreboard: false,
};

const gameSlice = createSlice({
  name: 'game',
  initialState,
  reducers: {
    setStage: (state, action) => {
      state.stage = action.payload;
    },
    setGameMode: (state, action) => {
      state.gameMode = action.payload;
    },
    setSeriesLength: (state, action) => {
      state.seriesLength = Math.max(1, Number(action.payload) || 1);
    },
    setSeriesCurrentMatch: (state, action) => {
      state.seriesCurrentMatch = Math.max(1, Number(action.payload) || 1);
    },
    setSeriesResults: (state, action) => {
      state.seriesResults = Array.isArray(action.payload) ? action.payload : [];
    },
    setSeriesPlayerStats: (state, action) => {
      state.seriesPlayerStats = action.payload && typeof action.payload === 'object' ? action.payload : {};
    },
    setTournamentUserTeam: (state, action) => {
      state.tournamentUserTeam = action.payload || '';
    },
    setTournamentOpponentTeams: (state, action) => {
      state.tournamentOpponentTeams = Array.isArray(action.payload) ? action.payload : [];
    },
    setTournamentMatches: (state, action) => {
      state.tournamentMatches = Array.isArray(action.payload) ? action.payload : [];
    },
    setTournamentCurrentMatchId: (state, action) => {
      state.tournamentCurrentMatchId = action.payload || '';
    },
    setTournamentChampion: (state, action) => {
      state.tournamentChampion = action.payload || '';
    },
    setTournamentPlayerStats: (state, action) => {
      state.tournamentPlayerStats = action.payload && typeof action.payload === 'object' ? action.payload : {};
    },
    setCareerTeam: (state, action) => {
      state.careerTeam = action.payload || '';
    },
    setCareerPlayerProfile: (state, action) => {
      state.careerPlayerProfile = action.payload && typeof action.payload === 'object' ? action.payload : null;
    },
    setCareerDomesticCountry: (state, action) => {
      state.careerDomesticCountry = action.payload || '';
    },
    setCareerDomesticTeams: (state, action) => {
      state.careerDomesticTeams = Array.isArray(action.payload) ? action.payload : [];
    },
    setCareerGlobalPlayerPool: (state, action) => {
      state.careerGlobalPlayerPool = Array.isArray(action.payload) ? action.payload : [];
    },
    setCareerAuctionSummary: (state, action) => {
      state.careerAuctionSummary = action.payload && typeof action.payload === 'object' ? action.payload : null;
    },
    setCareerOffers: (state, action) => {
      state.careerOffers = Array.isArray(action.payload) ? action.payload : [];
    },
    setCareerRetired: (state, action) => {
      state.careerRetired = !!action.payload;
    },
    setCareerSeason: (state, action) => {
      state.careerSeason = Number(action.payload) || 0;
    },
    setCareerSeasonLength: (state, action) => {
      state.careerSeasonLength = action.payload || 'standard';
    },
    setCareerFormat: (state, action) => {
      state.careerFormat = action.payload || 't20';
    },
    setCareerMatchIndex: (state, action) => {
      state.careerMatchIndex = Number(action.payload) || 0;
    },
    setCareerSchedule: (state, action) => {
      state.careerSchedule = Array.isArray(action.payload) ? action.payload : [];
    },
    setCareerStandings: (state, action) => {
      state.careerStandings = action.payload && typeof action.payload === 'object' ? action.payload : {};
    },
    setCareerPlayerStats: (state, action) => {
      state.careerPlayerStats = action.payload && typeof action.payload === 'object' ? action.payload : {};
    },
    setCareerSeasonHistory: (state, action) => {
      state.careerSeasonHistory = Array.isArray(action.payload) ? action.payload : [];
    },
    setMatchTypeKey: (state, action) => {
      state.matchTypeKey = action.payload;
    },
    setOwnTeam: (state, action) => {
      state.ownTeam = action.payload;
      state.ownPlayingXI = [];
      state.ownBattingOrderIds = [];
      state.ownCustomPlayers = [];
      state.ownTeamRoles = {
        captainId: null,
        viceCaptainId: null,
        wicketKeeperId: null,
      };
    },
    setOpponentTeam: (state, action) => {
      state.opponentTeam = action.payload;
      state.opponentPlayingXI = [];
      state.opponentBattingOrderIds = [];
      state.opponentCustomPlayers = [];
      state.opponentTeamRoles = {
        captainId: null,
        viceCaptainId: null,
        wicketKeeperId: null,
      };
    },
    setOwnPlayingXI: (state, action) => {
      state.ownPlayingXI = Array.isArray(action.payload) ? action.payload : [];
      state.ownBattingOrderIds = [];
    },
    setOpponentPlayingXI: (state, action) => {
      state.opponentPlayingXI = Array.isArray(action.payload) ? action.payload : [];
      state.opponentBattingOrderIds = [];
    },
    setOwnBattingOrderIds: (state, action) => {
      state.ownBattingOrderIds = Array.isArray(action.payload) ? action.payload : [];
    },
    setOpponentBattingOrderIds: (state, action) => {
      state.opponentBattingOrderIds = Array.isArray(action.payload) ? action.payload : [];
    },
    setOwnCustomPlayers: (state, action) => {
      state.ownCustomPlayers = Array.isArray(action.payload) ? action.payload : [];
    },
    setOpponentCustomPlayers: (state, action) => {
      state.opponentCustomPlayers = Array.isArray(action.payload) ? action.payload : [];
    },
    setOwnTeamRoles: (state, action) => {
      const payload = action.payload || {};
      state.ownTeamRoles = {
        captainId: payload.captainId ?? null,
        viceCaptainId: payload.viceCaptainId ?? null,
        wicketKeeperId: payload.wicketKeeperId ?? null,
      };
    },
    setOpponentTeamRoles: (state, action) => {
      const payload = action.payload || {};
      state.opponentTeamRoles = {
        captainId: payload.captainId ?? null,
        viceCaptainId: payload.viceCaptainId ?? null,
        wicketKeeperId: payload.wicketKeeperId ?? null,
      };
    },
    setLocationCountry: (state, action) => {
      state.locationCountry = action.payload;
    },
    setSelectedStadium: (state, action) => {
      state.selectedStadium = action.payload;
    },
    setCommentator: (state, action) => {
      state.commentator = action.payload;
    },
    setTossWinner: (state, action) => {
      state.tossWinner = action.payload;
    },
    setTossDecision: (state, action) => {
      state.tossDecision = action.payload;
    },
    setTossCall: (state, action) => {
      state.tossCall = action.payload;
    },
    setFirstBattingSide: (state, action) => {
      state.firstBattingSide = action.payload;
    },
    setMatchCondition: (state, action) => {
      state.matchCondition = action.payload;
    },
    setBattingIntent: (state, action) => {
      state.battingIntent = action.payload;
    },
    setBowlingIntent: (state, action) => {
      state.bowlingIntent = action.payload;
    },
    setFirstInnings: (state, action) => {
      state.firstInnings = action.payload;
    },
    setSecondInnings: (state, action) => {
      state.secondInnings = action.payload;
    },
    setShowScoreboard: (state, action) => {
      state.showScoreboard = action.payload;
    },
    toggleShowScoreboard: (state) => {
      state.showScoreboard = !state.showScoreboard;
    },
    hydrateGameState: (state, action) => {
      const payload = action.payload || {};
      const hasLegacyNoXI = payload.ownPlayingXI === undefined && payload.opponentPlayingXI === undefined;
      const stageValue = payload.stage;
      const migratedStage =
        hasLegacyNoXI && Number.isInteger(stageValue) && stageValue >= 9 && stageValue <= 11
          ? stageValue + 2
          : stageValue;
      return {
        ...state,
        ...payload,
        stage: migratedStage ?? state.stage,
        gameMode: payload.gameMode || state.gameMode,
        seriesLength: Number(payload.seriesLength) > 0 ? Number(payload.seriesLength) : state.seriesLength,
        seriesCurrentMatch:
          Number(payload.seriesCurrentMatch) > 0 ? Number(payload.seriesCurrentMatch) : state.seriesCurrentMatch,
        seriesResults: Array.isArray(payload.seriesResults) ? payload.seriesResults : state.seriesResults,
        seriesPlayerStats:
          payload.seriesPlayerStats && typeof payload.seriesPlayerStats === 'object'
            ? payload.seriesPlayerStats
            : state.seriesPlayerStats,
        tournamentUserTeam: payload.tournamentUserTeam || state.tournamentUserTeam,
        tournamentOpponentTeams: Array.isArray(payload.tournamentOpponentTeams)
          ? payload.tournamentOpponentTeams
          : state.tournamentOpponentTeams,
        tournamentMatches: Array.isArray(payload.tournamentMatches)
          ? payload.tournamentMatches
          : state.tournamentMatches,
        tournamentCurrentMatchId: payload.tournamentCurrentMatchId || state.tournamentCurrentMatchId,
        tournamentChampion: payload.tournamentChampion || state.tournamentChampion,
        tournamentPlayerStats:
          payload.tournamentPlayerStats && typeof payload.tournamentPlayerStats === 'object'
            ? payload.tournamentPlayerStats
            : state.tournamentPlayerStats,
        careerTeam: payload.careerTeam || state.careerTeam,
        careerPlayerProfile:
          payload.careerPlayerProfile && typeof payload.careerPlayerProfile === 'object'
            ? payload.careerPlayerProfile
            : state.careerPlayerProfile,
        careerDomesticCountry: payload.careerDomesticCountry || state.careerDomesticCountry,
        careerDomesticTeams: Array.isArray(payload.careerDomesticTeams)
          ? payload.careerDomesticTeams
          : state.careerDomesticTeams,
        careerGlobalPlayerPool: Array.isArray(payload.careerGlobalPlayerPool)
          ? payload.careerGlobalPlayerPool
          : state.careerGlobalPlayerPool,
        careerAuctionSummary:
          payload.careerAuctionSummary && typeof payload.careerAuctionSummary === 'object'
            ? payload.careerAuctionSummary
            : state.careerAuctionSummary,
        careerOffers: Array.isArray(payload.careerOffers) ? payload.careerOffers : state.careerOffers,
        careerRetired: typeof payload.careerRetired === 'boolean' ? payload.careerRetired : state.careerRetired,
        careerSeason: Number(payload.careerSeason) >= 0 ? Number(payload.careerSeason) : state.careerSeason,
        careerSeasonLength: payload.careerSeasonLength || state.careerSeasonLength,
        careerFormat: payload.careerFormat || state.careerFormat,
        careerMatchIndex: Number(payload.careerMatchIndex) >= 0 ? Number(payload.careerMatchIndex) : state.careerMatchIndex,
        careerSchedule: Array.isArray(payload.careerSchedule) ? payload.careerSchedule : state.careerSchedule,
        careerStandings:
          payload.careerStandings && typeof payload.careerStandings === 'object'
            ? payload.careerStandings
            : state.careerStandings,
        careerPlayerStats:
          payload.careerPlayerStats && typeof payload.careerPlayerStats === 'object'
            ? payload.careerPlayerStats
            : state.careerPlayerStats,
        careerSeasonHistory: Array.isArray(payload.careerSeasonHistory)
          ? payload.careerSeasonHistory
          : state.careerSeasonHistory,
        ownPlayingXI: Array.isArray(payload.ownPlayingXI) ? payload.ownPlayingXI : state.ownPlayingXI,
        opponentPlayingXI: Array.isArray(payload.opponentPlayingXI)
          ? payload.opponentPlayingXI
          : state.opponentPlayingXI,
        ownBattingOrderIds: Array.isArray(payload.ownBattingOrderIds)
          ? payload.ownBattingOrderIds
          : state.ownBattingOrderIds,
        opponentBattingOrderIds: Array.isArray(payload.opponentBattingOrderIds)
          ? payload.opponentBattingOrderIds
          : state.opponentBattingOrderIds,
        ownCustomPlayers: Array.isArray(payload.ownCustomPlayers)
          ? payload.ownCustomPlayers
          : state.ownCustomPlayers,
        opponentCustomPlayers: Array.isArray(payload.opponentCustomPlayers)
          ? payload.opponentCustomPlayers
          : state.opponentCustomPlayers,
        ownTeamRoles: payload.ownTeamRoles || state.ownTeamRoles,
        opponentTeamRoles: payload.opponentTeamRoles || state.opponentTeamRoles,
        firstInnings: {
          ...buildInitialInnings(),
          ...(payload.firstInnings || state.firstInnings),
        },
        secondInnings: {
          ...buildInitialInnings(),
          ...(payload.secondInnings || state.secondInnings),
        },
      };
    },
    resetMatchRuntime: (state) => {
      state.stage = matchStatusEnum.intro;
      state.gameMode = 'quick';
      state.seriesLength = 1;
      state.seriesCurrentMatch = 1;
      state.seriesResults = [];
      state.seriesPlayerStats = {};
      state.tournamentUserTeam = '';
      state.tournamentOpponentTeams = [];
      state.tournamentMatches = [];
      state.tournamentCurrentMatchId = '';
      state.tournamentChampion = '';
      state.tournamentPlayerStats = {};
      state.matchTypeKey = '';
      state.ownTeam = '';
      state.opponentTeam = '';
      state.locationCountry = '';
      state.selectedStadium = '';
      state.commentator = '';
      state.tossWinner = '';
      state.tossDecision = '';
      state.tossCall = '';
      state.firstBattingSide = '';
      state.ownPlayingXI = [];
      state.opponentPlayingXI = [];
      state.ownBattingOrderIds = [];
      state.opponentBattingOrderIds = [];
      state.ownCustomPlayers = [];
      state.opponentCustomPlayers = [];
      state.ownTeamRoles = {
        captainId: null,
        viceCaptainId: null,
        wicketKeeperId: null,
      };
      state.opponentTeamRoles = {
        captainId: null,
        viceCaptainId: null,
        wicketKeeperId: null,
      };
      state.matchCondition = buildEmptyMatchCondition();
      state.battingIntent = battingAction.normal;
      state.bowlingIntent = bowlingAction.normal;
      state.firstInnings = buildInitialInnings();
      state.secondInnings = buildInitialInnings();
      state.showScoreboard = false;
      state.careerTeam = '';
      state.careerPlayerProfile = null;
      state.careerDomesticCountry = '';
      state.careerDomesticTeams = [];
      state.careerGlobalPlayerPool = [];
      state.careerAuctionSummary = null;
      state.careerOffers = [];
      state.careerRetired = false;
      state.careerSeason = 0;
      state.careerSeasonLength = 'standard';
      state.careerFormat = 't20';
      state.careerMatchIndex = 0;
      state.careerSchedule = [];
      state.careerStandings = {};
      state.careerPlayerStats = {};
      state.careerSeasonHistory = [];
    },
    resetMatchForCareer: (state) => {
      state.matchTypeKey = '';
      state.ownTeam = state.careerTeam;
      state.opponentTeam = '';
      state.locationCountry = '';
      state.selectedStadium = '';
      state.tossWinner = '';
      state.tossDecision = '';
      state.tossCall = '';
      state.firstBattingSide = '';
      state.ownPlayingXI = [];
      state.opponentPlayingXI = [];
      state.ownBattingOrderIds = [];
      state.opponentBattingOrderIds = [];
      state.ownCustomPlayers = [];
      state.opponentCustomPlayers = [];
      state.ownTeamRoles = {
        captainId: null,
        viceCaptainId: null,
        wicketKeeperId: null,
      };
      state.opponentTeamRoles = {
        captainId: null,
        viceCaptainId: null,
        wicketKeeperId: null,
      };
      state.matchCondition = buildEmptyMatchCondition();
      state.battingIntent = battingAction.normal;
      state.bowlingIntent = bowlingAction.normal;
      state.firstInnings = buildInitialInnings();
      state.secondInnings = buildInitialInnings();
      state.showScoreboard = false;
    },
  },
});

export const {
  setStage,
  setGameMode,
  setSeriesLength,
  setSeriesCurrentMatch,
  setSeriesResults,
  setSeriesPlayerStats,
  setTournamentUserTeam,
  setTournamentOpponentTeams,
  setTournamentMatches,
  setTournamentCurrentMatchId,
  setTournamentChampion,
  setTournamentPlayerStats,
  setMatchTypeKey,
  setOwnTeam,
  setOpponentTeam,
  setOwnPlayingXI,
  setOpponentPlayingXI,
  setOwnBattingOrderIds,
  setOpponentBattingOrderIds,
  setOwnCustomPlayers,
  setOpponentCustomPlayers,
  setOwnTeamRoles,
  setOpponentTeamRoles,
  setLocationCountry,
  setSelectedStadium,
  setCommentator,
  setTossWinner,
  setTossDecision,
  setTossCall,
  setFirstBattingSide,
  setMatchCondition,
  setBattingIntent,
  setBowlingIntent,
  setFirstInnings,
  setSecondInnings,
  setShowScoreboard,
  toggleShowScoreboard,
  hydrateGameState,
  resetMatchRuntime,
  setCareerTeam,
  setCareerPlayerProfile,
  setCareerDomesticCountry,
  setCareerDomesticTeams,
  setCareerGlobalPlayerPool,
  setCareerAuctionSummary,
  setCareerOffers,
  setCareerRetired,
  setCareerSeason,
  setCareerSeasonLength,
  setCareerFormat,
  setCareerMatchIndex,
  setCareerSchedule,
  setCareerStandings,
  setCareerPlayerStats,
  setCareerSeasonHistory,
  resetMatchForCareer,
} = gameSlice.actions;

export default gameSlice.reducer;
